<?php
require '../config.php';require '../auth.php';require '../helpers.php';require_admin();$rows=$conn->query('SELECT b.*,u.name,u.email,f.facility_name,c.court_name,ts.start_time,ts.end_time FROM bookings b JOIN users u ON u.id=b.user_id JOIN courts c ON c.id=b.court_id JOIN facilities f ON f.id=c.facility_id JOIN time_slots ts ON ts.id=b.time_slot_id ORDER BY b.booking_date DESC,ts.start_time')->fetch_all(MYSQLI_ASSOC);$pageTitle='Manage Bookings';require 'partials/header.php';?>
<h1>All Bookings</h1><div class="table-wrap"><table><tr><th>User</th><th>Facility</th><th>Date and Time</th><th>Purpose</th><th>People</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $b):?><tr><td><?=htmlspecialchars($b['name'])?><br><small><?=htmlspecialchars($b['email'])?></small></td><td><?=htmlspecialchars($b['facility_name'].' - '.$b['court_name'])?></td><td><?=htmlspecialchars(date('d M Y',strtotime($b['booking_date'])))?><br><?=htmlspecialchars(slot_label($b['start_time'],$b['end_time']))?></td><td><?=htmlspecialchars($b['purpose'])?></td><td><?=(int)$b['participants']?></td><td><?=htmlspecialchars(ucfirst($b['status']))?></td><td><?php if($b['status']==='confirmed'):?><form method="post" action="booking_cancel.php" onsubmit="return confirm('Cancel this booking?')"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><button class="btn-small btn-danger">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php require 'partials/footer.php';?>

